const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, param, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for specific endpoints if needed
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: { error: 'Too many requests, please try again later.' },
});

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
const requestLogger = (req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - ${req.ip}`);
  next();
};
app.use(requestLogger);

// Validation error handler middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// Health check - minimal info exposure
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// Users endpoint with validation schema ready for future input
app.get('/users',
  [
    // Optional query parameter validation example
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
    handleValidationErrors
  ],
  (req, res) => {
    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];
      res.json(users);
    } catch (error) {
      console.error('Error fetching users:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// Example POST endpoint with full validation
app.post('/users',
  strictLimiter, // Apply stricter rate limiting to creation endpoint
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
      .matches(/^[a-zA-Z0-9\s-_]+$/).withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 255 }).withMessage('Email too long'),
    handleValidationErrors
  ],
  (req, res) => {
    try {
      const { name, email } = req.body;

      // Sanitize inputs
      const sanitizedName = name.trim().replace(/[<>]/g, '');

      // In a real app, you'd save to database here
      const newUser = {
        id: Date.now(), // Temporary ID generation
        name: sanitizedName,
        email: email.toLowerCase()
      };

      res.status(201).json(newUser);
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// User by ID endpoint with parameter validation
app.get('/users/:id',
  [
    param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer'),
    handleValidationErrors
  ],
  (req, res) => {
    try {
      const userId = parseInt(req.params.id, 10);

      // Mock user lookup
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
