app.get('/health',
  query('detailed').optional().isBoolean().withMessage('detailed must be a boolean'),
  handleValidationErrors,
  (req, res) => {
    const health = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    logger.info('Health check accessed', { ip: req.ip });
    res.json(health);
  }
);

// Users endpoint with pagination and search validation
app.get('/users',
  query('page').optional().isInt({ min: 1, max: 1000 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('search').optional().trim().escape().isLength({ max: 100 }).withMessage('Search term too long'),
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const page = parseInt(req.query.page) || 1;
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const search = req.query.search;

    // Simulate database query with sanitization
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter if provided (sanitized)
    if (search) {
      users = users.filter(user => 
        user.name.toLowerCase().includes(search.toLowerCase()) ||
        user.email.toLowerCase().includes(search.toLowerCase())
      );
    }

    logger.info('Users list accessed', { ip: req.ip, page, limit, search: search ? 'provided' : 'none' });

    res.json({
      users,
      pagination: {
        page,
        limit,
        total: users.length
      }
    });
  })
);

// Example of a POST endpoint with comprehensive validation
app.post('/users',
  strictLimiter,
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2-100 characters')
      .matches(/^[a-zA-Z0-9\s'-]+$/).withMessage('Name contains invalid characters')
      .escape(),
    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 255 }).withMessage('Email too long'),
    body('age')
      .optional()
      .isInt({ min: 13, max: 120 }).withMessage('Age must be between 13 and 120')
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { name, email, age } = req.body;

    // Simulate user creation
    const newUser = {
      id: Date.now(), // In production, use UUID
      name,
      email,
      age,
      createdAt: new Date().toISOString()
    };

    logger.info('New user created', { userId: newUser.id, email });

    res.status(201).json({
      message: 'User created successfully',
      user: newUser
    });
  })
);

// Security: 404 handler
app.use((req, res) => {
  logger.warn('404 Not Found', { path: req.path, method: req.method, ip: req.ip });
  res.status(404).json({ error: 'Resource not found' });
});

// Security: Global error handler - prevents information leakage
app.use((err, req, res, next) => {
  // Log full error details internally
  logger.error('Unhandled error', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Send generic error to client
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.status === 400 ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// Graceful shutdown handling
const server = app.listen(process.env.PORT || 3000, () => {
  logger.info(`Server running on port ${process.env.PORT || 3000}`);
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception', { error: err.message, stack: err.stack });
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection', { reason });
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  logger.info(`${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    logger.info('Server closed. Process terminated.');
    process.exit(0);
  });
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

