app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security: Input validation helper
const validateInput = (value, type, options = {}) => {
  if (value === undefined || value === null) {
    return options.default !== undefined ? { valid: true, value: options.default } : { valid: false, error: 'Missing required input' };
  }

  switch (type) {
    case 'string':
      if (typeof value !== 'string') return { valid: false, error: 'Expected string' };
      if (options.maxLength && value.length > options.maxLength) return { valid: false, error: `Exceeds max length of ${options.maxLength}` };
      if (options.pattern && !options.pattern.test(value)) return { valid: false, error: 'Invalid format' };
      return { valid: true, value: value.trim() };

    case 'integer':
      const num = parseInt(value, 10);
      if (!Number.isFinite(num)) return { valid: false, error: 'Invalid integer' };
      if (options.min !== undefined && num < options.min) return { valid: false, error: `Must be >= ${options.min}` };
      if (options.max !== undefined && num > options.max) return { valid: false, error: `Must be <= ${options.max}` };
      return { valid: true, value: num };

    default:
      return { valid: false, error: 'Unknown validation type' };
  }
};

// Security: Input sanitization helper
const sanitizeResponse = (data) => {
  // Remove any sensitive fields before sending response
  if (Array.isArray(data)) {
    return data.map(item => sanitizeResponse(item));
  }
  if (typeof data === 'object' && data !== null) {
    const sanitized = { ...data };
    // Remove sensitive fields
    delete sanitized.password;
    delete sanitized.token;
    delete sanitized.secret;
    delete sanitized.apiKey;
    delete sanitized.internalNotes;
    return sanitized;
  }
  return data;
};

