const request = require('supertest');
const app = require('../app');

describe('Security Features', () => {
  describe('HTTP Headers', () => {
    it('should set security headers via helmet', async () => {
      const response = await request(app).get('/health');

      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers['x-frame-options']).toBe('DENY');
      expect(response.headers['content-security-policy']).toBeDefined();
      expect(response.headers['x-request-id']).toBeDefined();
    });
  });

  describe('Input Validation', () => {
    it('should reject negative ID parameter', async () => {
      const response = await request(app)
        .get('/users/-1')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
      expect(response.body.details).toContainEqual(
        expect.objectContaining({
          field: 'id',
          message: 'User ID must be a positive integer'
        })
      );
    });

    it('should reject non-numeric ID parameter', async () => {
      const response = await request(app)
        .get('/users/abc')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    it('should reject SQL injection attempts in ID', async () => {
      const response = await request(app)
        .get('/users/1 OR 1=1')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    it('should reject XSS attempts in ID', async () => {
      const response = await request(app)
        .get('/users/<script>alert(1)</script>')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });
  });

  describe('Rate Limiting', () => {
    // Note: Rate limiting tests may be affected by test execution order
    // In a real scenario, use a redis store for consistent rate limiting
    it('should indicate rate limit headers are present', async () => {
      const response = await request(app).get('/health');

      expect(response.headers['ratelimit-limit']).toBeDefined();
      expect(response.headers['ratelimit-remaining']).toBeDefined();
    });
  });

  describe('Error Handling', () => {
    it('should not expose stack traces in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/nonexistent')
        .expect(404);

      expect(response.body.stack).toBeUndefined();
      expect(response.body.details).toBeUndefined();
      expect(response.body.error).toBeDefined();
      expect(response.body.requestId).toBeDefined();

      process.env.NODE_ENV = originalEnv;
    });

    it('should include requestId in error responses', async () => {
      const response = await request(app).get('/users/999');

      expect(response.body.requestId).toBeDefined();
      expect(typeof response.body.requestId).toBe('string');
    });
  });

  describe('CORS', () => {
    it('should handle CORS preflight requests', async () => {
      const response = await request(app)
        .options('/health')
        .set('Origin', 'http://localhost:3000')
        .set('Access-Control-Request-Method', 'GET');

      expect(response.headers['access-control-allow-origin']).toBeDefined();
    });
  });

  describe('Request Size Limits', () => {
    it('should reject requests with body exceeding size limit', async () => {
      const largeBody = 'x'.repeat(20000);

      const response = await request(app)
        .post('/any-endpoint')
        .send({ data: largeBody })
        .expect(413);
    });
  });
});

describe('Health Endpoint', () => {
  it('should return health status', async () => {
    const response = await request(app)
      .get('/health')
      .expect(200);

    expect(response.body.status).toBe('ok');
    expect(response.body.timestamp).toBeDefined();
    expect(response.body.requestId).toBeDefined();
  });
});

describe('Users Endpoint', () => {
  it('should return list of users', async () => {
    const response = await request(app)
      .get('/users')
      .expect(200);

    expect(Array.isArray(response.body)).toBe(true);
    expect(response.body).toHaveLength(2);
    expect(response.body[0]).toHaveProperty('id');
    expect(response.body[0]).toHaveProperty('name');
    expect(response.body[0]).toHaveProperty('email');
  });

  it('should return single user by ID', async () => {
    const response = await request(app)
      .get('/users/1')
      .expect(200);

    expect(response.body.id).toBe(1);
    expect(response.body.name).toBe('Alice');
